mod norm;
#[path="../lazy-certificate/core.rs"]mod core;
#[path="../batched/inverse.rs"]mod inverse;
use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::{Curve,Div},instance::factor_base,rng::Rng};
type Points=Vec<(usize,usize,bool,u64)>;
fn implicit(c:&Curve,a:&Div,reps:&[(u64,u64)])->Vec<Poly>{let f=&c.fp;let mut out=vec![];for &(x,y)in reps{let r=f.pow(x,5);for yy in[y,f.neg(y)]{out.push(norm::norm(Poly::from_coeffs(&[0,1]),Poly::from_coeffs(&[a.v.c[1],a.u.c[1]]),Poly::from_coeffs(&[f.sub(a.v.c[0],yy),a.u.c[0]]),r,f));}}out}
fn direct(c:&Curve,a:&Div,reps:&[(u64,u64)],z:u64)->Vec<Poly>{let f=&c.fp;let mut out=vec![];for &(x,y)in reps{let mut polys=[Poly::one();2];let mut xx=x;for _ in 0..5{let u=a.u.eval(xx,f);let v=a.v.eval(xx,f);for(sign,yy)in[y,f.neg(y)].into_iter().enumerate(){polys[sign]=polys[sign].mul(&Poly::from_coeffs(&[f.sub(v,yy),u]),f);}xx=f.mul(xx,z);}out.extend(polys);}out}
fn explicit(c:&Curve,a:&Div,reps:&[(u64,u64)],z:u64)->Points{let f=&c.fp;let mut entries=vec![];let mut den=vec![];for(i,&(x,y))in reps.iter().enumerate(){let mut xx=x;for e in 0..5{let u=a.u.eval(xx,f);if u!=0{entries.push((i,e,y,a.v.eval(xx,f)));den.push(u);}xx=f.mul(xx,z);}}let inv=inverse::invert(&den,f);let mut out=vec![];for(&(i,e,y,v),iv)in entries.iter().zip(inv){out.push((i,e,false,f.mul(f.sub(y,v),iv)));out.push((i,e,true,f.mul(f.sub(f.neg(y),v),iv)));}out}
fn main(){counted::disable();println!("p\tsm\tcase\trep\tkernel\tmodulus\tanchors\torbits\tcounts");let mut panels=0;for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let pt=fb[0];let base=c.place(pt.0,pt.1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let target=c.mul(&d,k);let mut successful=None;for seed in 1..=3{let tr=core::solve(&c,pt,&d,&target,ell,sm,seed,false,true);if tr.answer.is_some(){successful=Some(tr);break}}let tr=successful.unwrap();assert_eq!(tr.answer.map(|x|x.1),Some(k));let mut anchors=vec![];let mut a=target;for _ in 0..16{a=c.add(&a,&d);if a.u.deg()==2{anchors.push(a)}}let mut first=None;for rep in 0..2{counted::reset();let ii:Vec<_>=anchors.iter().map(|a|implicit(&c,a,&tr.points)).collect();let ci=counted::snapshot();counted::disable();counted::reset();let dd:Vec<_>=anchors.iter().map(|a|direct(&c,a,&tr.points,tr.z)).collect();let cd=counted::snapshot();counted::disable();assert_eq!(ii,dd);counted::reset();let ee:Vec<_>=anchors.iter().map(|a|explicit(&c,a,&tr.points,tr.z)).collect();let ce=counted::snapshot();counted::disable();for(rows,params)in ii.iter().zip(&ee){for &(i,_,negative,t)in params{assert_eq!(rows[2*i+usize::from(negative)].eval(t,&c.fp),0);}}let signature=(ci.clone(),cd.clone(),ce.clone());if let Some(ref prev)=first{assert_eq!(prev,&signature)}else{first=Some(signature)}for(name,counts)in[("implicit_norm",ci),("direct_polynomial",cd),("explicit_parameters",ce)]{for(m,v)in counts{assert_eq!(m,p);assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{name}\t{m}\t{}\t{}\t{}",anchors.len(),tr.points.len(),v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}}}panels+=1;}}}assert_eq!(panels,12);eprintln!("panels=12 kernel_calls=72 original_target_scalars=true coefficient_products_exact=true explicit_parameter_roots_exact=true repeats_exact=true common_diagnostic_setup_excluded_all_arms=true component_only=true independent_verification=false");}
